// Generated by scripts/build-madi-games.mjs. Edit source/ instead.
// The Revenue Dragon - Three.js Game

let scene, camera, renderer, clock;

let player;

let dragon;

let beams = [];

let fireballs = [];

let score = 0;

let dragonHP = 100;

let gameActive = false;
let battleTime = 0;
let fireHeld = false;


// Movement params
let playerX = 0;

let moveDir = 0;
 // -1 = Left, 1 = Right
const speed = 10.0;

let fireCooldown = 0;


// DOM Elements
const startScreen = document.getElementById('TEMPLATE-4weird-start-screen');

const pauseScreen = document.getElementById('TEMPLATE-4weird-pause-screen');

const gameOverScreen = document.getElementById('TEMPLATE-4weird-game-over-screen');

const startBtn = document.getElementById('TEMPLATE-4weird-start-btn');

const resumeBtn = document.getElementById('TEMPLATE-4weird-resume-btn');

const restartBtn = document.getElementById('TEMPLATE-4weird-restart-btn');

const playAgainBtn = document.getElementById('TEMPLATE-4weird-play-again-btn');

const scoreSpan = document.getElementById('game-score');

const finalScoreSpan = document.getElementById('final-score-val');

const dragonHPBar = document.getElementById('dragon-hp-bar');

const endTitle = document.getElementById('end-title');

const endDesc = document.getElementById('end-desc');


init();


let spawnTimer = 0;



// Expose VibeCodeWorker state
window.gameState = { title: "the-revenue-dragon", get active() { return typeof gameActive !== "undefined" ? gameActive : true; } };

window.game = window.gameState;


/* fourweird-fullscreen-patch: refit canvas on fullscreen transitions (button/F/dblclick handled in index.html). */
(function () {
  'use strict';
  try {
    function fwRefit() {
      try {
        if (typeof onWindowResize === 'function') { onWindowResize(); }
      } catch (e) {}
      try {
        var fs = !!(document.fullscreenElement || document.webkitFullscreenElement);
        if (document.body) { document.body.classList.toggle('is-fullscreen', fs); }
        var f = document.querySelector('.TEMPLATE-4weird-game-frame');
        if (f) { f.classList.toggle('is-fullscreen', fs); }
      } catch (e) {}
    }
    document.addEventListener('fullscreenchange', fwRefit);
    document.addEventListener('webkitfullscreenchange', fwRefit);
    window.addEventListener('fourweird-fullscreen', fwRefit);
  } catch (e) {}
})();





function init() {
    scene = new THREE.Scene();
    scene.background = new THREE.Color(0x0a0202);
    scene.fog = new THREE.FogExp2(0x0a0202, 0.02);

    camera = new THREE.PerspectiveCamera(60, 800 / 600, 0.1, 100);
    camera.position.set(0, 0, 10);

    const canvas = document.getElementById('TEMPLATE-4weird-gameCanvas');
    renderer = new THREE.WebGLRenderer({ canvas: canvas, antialias: true });
    renderer.setSize(canvas.clientWidth, canvas.clientHeight);

    clock = new THREE.Clock();

    // Lighting
    const ambientLight = new THREE.AmbientLight(0xffffff, 0.3);
    scene.add(ambientLight);

    const redLight = new THREE.PointLight(0xef4444, 2, 40);
    redLight.position.set(0, 3, 5);
    scene.add(redLight);

    // Create player cats
    createPlayer();

    // Create the dragon
    createDragon();

    // Event listeners
    window.addEventListener('keydown', onKeyDown);
    window.addEventListener('keyup', onKeyUp);
    startBtn.addEventListener('click', startGame);
    resumeBtn.addEventListener('click', resumeGame);
    restartBtn.addEventListener('click', resetGame);
    playAgainBtn.addEventListener('click', resetGame);

    // Mobile Virtual controls steering
    const btnLeft = document.getElementById('btn-left');
    const btnRight = document.getElementById('btn-right');
    const btnFire = document.getElementById('btn-fire');
    btnFire.addEventListener('pointerdown', () => { fireHeld = gameActive; });
    for (const type of ['pointerup', 'pointerleave', 'pointercancel']) {
        btnFire.addEventListener(type, () => { fireHeld = false; });
    }

    const setLeft = (e) => { e.preventDefault(); moveDir = -1; };
    const setRight = (e) => { e.preventDefault(); moveDir = 1; };
    const clearMove = (e) => { e.preventDefault(); moveDir = 0; };

    btnLeft.addEventListener('mousedown', setLeft);
    btnLeft.addEventListener('touchstart', setLeft);
    btnLeft.addEventListener('mouseup', clearMove);
    btnLeft.addEventListener('touchend', clearMove);
    btnLeft.addEventListener('mouseleave', clearMove);

    btnRight.addEventListener('mousedown', setRight);
    btnRight.addEventListener('touchstart', setRight);
    btnRight.addEventListener('mouseup', clearMove);
    btnRight.addEventListener('touchend', clearMove);
    btnRight.addEventListener('mouseleave', clearMove);

    btnFire.addEventListener('click', (e) => {
        e.preventDefault();
        fireBeam();
    });
    btnFire.addEventListener('touchstart', (e) => {
        e.preventDefault();
        fireBeam();
    });

    window.addEventListener('resize', onWindowResize);
    onWindowResize();

    animate();
}



function createPlayer() {
    player = new THREE.Group();

    // Blue Cat body
    const blueMat = new THREE.MeshPhongMaterial({ color: 0x3b82f6 });
    const blueGeo = new THREE.BoxGeometry(0.7, 0.7, 0.7);
    const blue = new THREE.Mesh(blueGeo, blueMat);
    blue.position.x = -0.3;
    player.add(blue);

    // Green Cat body
    const greenMat = new THREE.MeshPhongMaterial({ color: 0x10b981 });
    const green = new THREE.Mesh(blueGeo, greenMat);
    green.position.x = 0.3;
    player.add(green);

    player.position.set(0, -4, 0);
    scene.add(player);
}


function createDragon() {
    dragon = new THREE.Group();

    const partGeo = new THREE.BoxGeometry(1.5, 1.2, 1.2);
    const dragMat = new THREE.MeshPhongMaterial({ color: 0xef4444, emissive: 0x4a0404, shininess: 80 });

    // Main head segment
    const head = new THREE.Mesh(partGeo, dragMat);
    dragon.add(head);

    // Left wing
    const leftWing = new THREE.Mesh(new THREE.BoxGeometry(2, 0.4, 0.8), dragMat);
    leftWing.position.set(-1.8, 0.3, -0.2);
    dragon.add(leftWing);

    // Right wing
    const rightWing = leftWing.clone();
    rightWing.position.x = 1.8;
    dragon.add(rightWing);

    // Horns
    const hornGeo = new THREE.ConeGeometry(0.2, 0.8, 4);
    const hornMat = new THREE.MeshBasicMaterial({ color: 0xf97316 });
    const hornL = new THREE.Mesh(hornGeo, hornMat);
    hornL.position.set(-0.5, 0.8, 0);
    const hornR = hornL.clone();
    hornR.position.x = 0.5;
    dragon.add(hornL);
    dragon.add(hornR);

    dragon.position.set(0, 3, 0);
    scene.add(dragon);
}


function fireBeam() {
    if (!gameActive || fireCooldown > 0) return;
    fireCooldown = 0.25; // rate of fire limit

    const beamGeo = new THREE.CylinderGeometry(0.1, 0.1, 0.8, 8);
    const beamMat = new THREE.MeshBasicMaterial({ color: 0x60a5fa });
    const beam = new THREE.Mesh(beamGeo, beamMat);
    beam.position.set(playerX, -3.5, 0);
    scene.add(beam);
    beams.push(beam);
}


function spawnFireball() {
    const ballGeo = new THREE.SphereGeometry(0.3, 16, 16);
    const ballMat = new THREE.MeshPhongMaterial({ color: 0xf97316, emissive: 0x7c2d12 });
    const ball = new THREE.Mesh(ballGeo, ballMat);

    // Spawn from dragon's horizontal position
    const dx = dragon.position.x + (Math.random() * 2 - 1);
    ball.position.set(dx, 2.5, 0);
    scene.add(ball);
    fireballs.push(ball);
}



function startGame() {
    fireHeld = false;
    pauseScreen.classList.add('hidden');
    clock.getDelta();
    startScreen.classList.add('hidden');
    gameOverScreen.classList.add('hidden');
    pauseScreen.classList.add('hidden');
    gameActive = true;
    clock.getDelta();
}


function pauseGame() {
    fireHeld = false;
    if (!gameActive) return;
    gameActive = false;
    pauseScreen.classList.remove('hidden');
}


function resumeGame() {
    if (pauseScreen.classList.contains('hidden')) return;
    clock.getDelta();
    pauseScreen.classList.add('hidden');
    gameActive = true;
}


function resetGame() {
    beams.forEach(b => scene.remove(b));
    fireballs.forEach(f => scene.remove(f));
    beams = [];
    fireballs = [];

    playerX = 0;
    score = 0;
    dragonHP = 100;
    battleTime = 0;
    spawnTimer = 0;
    fireCooldown = 0;
    moveDir = 0;
    syncDragonHealth();

    scoreSpan.textContent = '0';
    player.position.set(0, -4, 0);
    dragon.position.set(0, 3, 0);

    startGame();
}


function endBattle(won) {
    gameActive = false;
    if (won) {
        endTitle.textContent = "Dragon Defeated!";
        endDesc.textContent = "Manual processes cleared. Growth speed unlocked!";
    } else {
        endTitle.textContent = "Defeated";
        endDesc.textContent = "You got caught in the data silos fire.";
    }
    finalScoreSpan.textContent = score;
    gameOverScreen.classList.remove('hidden');
}



function onKeyDown(e) {
    if (e.target && e.target.matches && e.target.matches('input, textarea, select, [contenteditable="true"]')) return;
    if (e.repeat && ['Escape', 'KeyP'].includes(e.code)) return;
    if (['Space', 'ArrowUp', 'ArrowDown', 'ArrowLeft', 'ArrowRight'].includes(e.code)) e.preventDefault();
    if (e.code === 'ArrowLeft' || e.code === 'KeyA') moveDir = -1;
    else if (e.code === 'ArrowRight' || e.code === 'KeyD') moveDir = 1;
    else if (e.code === 'Space') { fireHeld = gameActive; fireBeam(); }
    else if (e.code === 'KeyP' || e.code === 'Escape') {
        if (gameActive) pauseGame();
        else resumeGame();
    }
}


function onKeyUp(e) {
    if (e.code === 'Space') fireHeld = false;
    if ((e.code === 'ArrowLeft' || e.code === 'KeyA') && moveDir === -1) moveDir = 0;
    if ((e.code === 'ArrowRight' || e.code === 'KeyD') && moveDir === 1) moveDir = 0;
}


function onWindowResize() {
    const canvas = document.getElementById('TEMPLATE-4weird-gameCanvas');
    const w = canvas.clientWidth;
    const h = canvas.clientHeight;
    camera.aspect = w / h;
    camera.updateProjectionMatrix();
    renderer.setSize(w, h, false);
}



function animate() {
    requestAnimationFrame(animate);

    if (gameActive) {
        const delta = Math.min(clock.getDelta(), 0.05);
        battleTime += delta;

        // 1. Move player
        playerX += moveDir * speed * delta;
        playerX = Math.max(-5, Math.min(5, playerX));
        player.position.x = playerX;

        // Fire cooldown decrement
        if (fireCooldown > 0) fireCooldown -= delta;
        if (fireHeld) fireBeam();

        // 2. Dragon movement (hover back and forth)
        dragon.position.x = Math.sin(battleTime * 2) * 4;

        // Wings flap animation
        const flap = Math.sin(battleTime * 15) * 0.3;
        dragon.children[1].rotation.z = flap;
        dragon.children[2].rotation.z = -flap;

        // 3. Spawn fireballs
        spawnTimer += delta;
        if (spawnTimer > 0.8) {
            spawnFireball();
            spawnTimer = 0;
        }

        // 4. Update beams
        const dragBox = new THREE.Box3().setFromObject(dragon);
        for (let i = beams.length - 1; i >= 0; i--) {
            const beam = beams[i];
            beam.position.y += 12 * delta;

            const beamBox = new THREE.Box3().setFromObject(beam);
            if (beamBox.intersectsBox(dragBox)) {
                // hit
                scene.remove(beam);
                beams.splice(i, 1);

                dragonHP -= 4;
                score += 50;
                scoreSpan.textContent = score;
                syncDragonHealth();

                if (dragonHP <= 0) {
                    dragonHP = 0;
                    endBattle(true);
                    return;
                }
                continue;
            }

            if (beam.position.y > 6) {
                scene.remove(beam);
                beams.splice(i, 1);
            }
        }

        // 5. Update fireballs
        const playerBox = new THREE.Box3().setFromObject(player);
        for (let i = fireballs.length - 1; i >= 0; i--) {
            const ball = fireballs[i];
            ball.position.y -= 6 * delta;

            const ballBox = new THREE.Box3().setFromObject(ball);
            if (ballBox.intersectsBox(playerBox)) {
                endBattle(false);
                continue;
            }

            if (ball.position.y < -5) {
                scene.remove(ball);
                fireballs.splice(i, 1);
            }
        }
    }

    renderer.render(scene, camera);
}

// Pause before background time advances hazards.
(function () {
  function suspend() {
    moveDir = 0;
    if (gameActive) { pauseGame(); resumeBtn.focus({ preventScroll: true }); }
  }
  window.addEventListener('blur', suspend);
  window.addEventListener('pagehide', suspend);
  document.addEventListener('visibilitychange', () => { if (document.hidden) suspend(); });
})();

// A visible pause action and a short control reminder make every MADI run
// usable without memorizing the launch screen or reaching for a keyboard.
(function installMadiSessionControls() {
    if (typeof gameActive === 'undefined' || !pauseScreen || !renderer) return;
    const instructions = {
        'temple-of-lost-revenue': 'Move: WASD / arrows or direction buttons. Collect all five gold leads. Map: cyan = you; gold = remaining leads.',
        'the-ai-expedition': 'Click or tap each blue outer node to connect it to the center. Connect all four to synchronize the network.',
        'the-cave-of-bottlenecks': 'Hold A / D, arrows, or the direction buttons to aim. Keep the beam on a red target until it clears.',
        'the-lost-city-of-customers': 'Click or tap terrain to scan. A nearby scan reveals gold targets; scan directly beneath one to capture it.',
        'the-pipeline-mountain': 'Hold A / D, arrows, or direction buttons to steer. Jumps happen automatically when you land on a platform.',
        'the-revenue-dragon': 'A / D or arrows move. Hold Space or the fire button to shoot. Dodge fireballs and drain the dragon’s health.',
        'the-revenue-jungle': 'Space, Up, or a tap on the arena leaps over obstacles. Time each jump as the obstacle approaches.',
        'the-speed-portal': 'A / D, arrows, or direction buttons rotate around the tunnel. Avoid obstacles and collect speed rings.',
        'treasure-hunters': 'Space or a click/tap on the arena extends the claw. Time the swing to retrieve valuable items.'
    };
    const title = window.gameState && window.gameState.title;
    const reminder = document.createElement('p');
    reminder.textContent = instructions[title] || 'Resume your run or restart for a fresh attempt.';
    Object.assign(reminder.style, {
        font: '13px/1.45 system-ui', color: '#cbd5e1', maxWidth: '360px',
        padding: '0 12px', margin: '12px auto 0', textAlign: 'center'
    });
    pauseScreen.appendChild(reminder);

    const pause = document.createElement('button');
    pause.type = 'button';
    pause.textContent = 'Ⅱ Pause';
    pause.setAttribute('aria-label', 'Pause game and review controls');
    Object.assign(pause.style, {
        position: 'absolute', right: '12px', bottom: '12px', zIndex: '20',
        minHeight: '40px', padding: '7px 12px', border: '1px solid #64748b',
        borderRadius: '8px', color: '#f8fafc', background: '#0f172ae8',
        font: '600 13px system-ui', cursor: 'pointer'
    });
    pause.addEventListener('keydown', event => event.stopPropagation());
    pause.addEventListener('click', event => {
        event.stopPropagation();
        if (!gameActive) return;
        pauseGame();
        resumeBtn.focus({ preventScroll: true });
    });
    function refresh() { pause.hidden = !gameActive; pause.style.display = gameActive ? 'block' : 'none'; }
    const observer = new MutationObserver(refresh);
    for (const screen of [startScreen, pauseScreen, gameOverScreen]) {
        observer.observe(screen, { attributes: true, attributeFilter: ['class', 'style', 'hidden'] });
    }
    refresh();
    renderer.domElement.parentElement.appendChild(pause);
})();

function syncDragonHealth() {
    const track = document.getElementById('dragon-hp-container');
    if (!track) return;
    let value = document.getElementById('dragon-health-value');
    if (!value) {
        value = document.createElement('span');
        value.id = 'dragon-health-value';
        track.style.position = 'relative';
        Object.assign(value.style, { position: 'absolute', inset: '0', textAlign: 'center', font: '700 12px/20px system-ui', color: '#fff', textShadow: '0 1px 2px #000' });
        track.appendChild(value);
        track.setAttribute('role', 'progressbar');
        track.setAttribute('aria-label', 'Dragon health');
        track.setAttribute('aria-valuemin', '0');
        track.setAttribute('aria-valuemax', '100');
    }
    const percent = Math.max(0, Math.min(100, dragonHP));
    dragonHPBar.style.width = percent + '%';
    track.setAttribute('aria-valuenow', String(percent));
    value.textContent = percent + '%';
}
syncDragonHealth();
